    k = p["k"]
    l0 = p["l0"]
    m = p["m"]
    _t0 = m * l
    _t1 = m * g
    _t2 = np.cross(q, e3) * (_t1 * l * -1)
    out = np.zeros(4)
    out[0] = _t0 * (omega_q @ omega_q) + _t1 * (q @ e3) * -1 + k * l * -1 + k * l0
    out[1:4] = omega_q * (_t0 * l_dot * -2) + _t2
